def game(A, B):
    if A == 0 and B == 0:
        return "Non-drinkers can't play"
    mike_total = 0
    joe_total = 0
    turn = 1
    while True:
        if turn % 2 == 1:
            if mike_total + turn > A:
                return "Joe"
            mike_total += turn
        else:
            if joe_total + turn > B:
                return "Mike"
            joe_total += turn
        turn += 1
